'use strict';
/* Deliberately standalone public UI prototype, not the Next.js application.
   All data is synthetic. No network, auth, clinical output or payment calls. */
const $ = (q, root = document) => root.querySelector(q);
const escapeHTML = (v) => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  arrow:'M5 12h14m-6-6 6 6-6 6', back:'m14 6-6 6 6 6', close:'m6 6 12 12M18 6 6 18',
  menu:'M4 7h16M4 12h16M4 17h16', search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  home:'m3 10 9-7 9 7v10H3Zm6 10v-7h6v7', calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2Zm2-3v6m10-6v6M3 10h18m-13 5h2m4 0h2',
  video:'M3 5h12v14H3Zm12 5 6-4v12l-6-4', user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0M4 22v-2a8 8 0 0 1 16 0v2',
  check:'m5 12 4 4L19 6', pin:'M12 22S3 14 3 9a9 9 0 1 1 18 0c0 5-9 13-9 13ZM9 9a3 3 0 1 0 6 0 3 3 0 0 0-6 0',
  clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 3', mail:'M2 5h20v14H2Zm0 0 10 8L22 5',
  shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Zm-5 10 3 3 7-7', lock:'M6 10h12v11H6Zm2 0V6a4 4 0 0 1 8 0v4',
  phone:'m5 2 4 4-2 4c2 4 3 5 7 7l4-2 4 4c-4 7-12 2-17-3S-2 3 5 2', play:'m8 4 12 8-12 8Z',
  info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 11v6m0-10v1', refresh:'M20 7a9 9 0 1 0 1 9M20 2v6h-6',
  chevron:'m9 5 7 7-7 7', document:'M5 2h9l5 5v15H5Zm9 0v6h5M8 12h8m-8 4h8', globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-6 6-6 14 0 20 6-6 6-14 0-20',
  wifi:'M2 8c6-6 14-6 20 0M6 12c4-4 8-4 12 0m-8 4c1-1 3-1 4 0m-2 4h.01', external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'
};
const icon = n => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n] || paths.arrow}"/></svg>`;
const logo = () => `<a class="brand" href="#/home" aria-label="PhysiX home"><svg class="brand-mark" viewBox="0 0 36 44" aria-hidden="true"><path fill="currentColor" d="M19 42C4 41 0 27 1 22c12 0 18 7 18 20Zm1-9c-1-18 7-25 15-26 1 17-5 24-15 26ZM16 21C7 17 7 7 11 1c9 4 10 14 5 20Z"/></svg><div><div class="wordmark">Physi<span>X</span></div><div class="brand-caption">PHYSIOTHERAPY</div></div></a>`;
const btn = (label, dest, type = '', ico = '') => `<a class="button ${type}" href="#/${dest}">${ico ? icon(ico) : ''}${label}${!ico && type !== 'secondary' ? icon('arrow') : ''}</a>`;
const textLink = (label, dest) => `<a class="text-link" href="#/${dest}">${label}${icon('arrow')}</a>`;
const assetURL = asset => window.PHYSIX_INLINE_ASSETS?.[asset] || `assets/${asset}.webp`;
const photo = (asset, cls = '', alt = '') => `<img src="${assetURL(asset)}" class="${cls}" alt="${escapeHTML(alt)}" width="260" height="297">`;
const notice = (text, type = '') => `<div class="notice ${type}">${text}</div>`;
const checkList = items => `<ul class="check-list">${items.map(s=>`<li>${icon('check')}<span>${s}</span></li>`).join('')}</ul>`;
const stepList = items => `<div class="steps">${items.map(([h,p],i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`;
let booking = {type:'first', mode:'clinic', date:'16', time:'10:00', name:'', email:'', phone:''};
let currentRoute = 'home';
let lastPublicRoute = 'home';
let activeFilter = 'All';
let searchQuery = 'back';
let serviceQuery = '';
const services = [
  {id:'sports',name:'Sports rehabilitation',short:'Sports rehab',asset:'sports',group:'Rehabilitation',area:'Knee Shoulder',copy:'Support for your return to the activities you enjoy.',intro:'A clear starting point for getting back to the movement that matters to you.'},
  {id:'manual',name:'Manual therapy',short:'Manual therapy',asset:'manual',group:'Pain & movement',area:'Back Neck Shoulder',copy:'Hands-on care, shaped around your assessment.',intro:'Hands-on care as part of an individual, assessment-led approach.'},
  {id:'movement',name:'Movement & mobility',short:'Movement & mobility',asset:'movement',group:'Pain & movement',area:'Back Posture Knee',copy:'Make everyday movement feel more manageable.',intro:'Understand how you move and explore the next steps with your physiotherapist.'}
];
const screenList = [
 ['home','Home','Full scrolling homepage; no stacked review card'],['services','Services','Search, categories and service list'],['services-loading','Services · loading','Non-interactive skeleton state'],
 ['service-sports','Sports rehabilitation','Service detail template'],['service-manual','Manual therapy','Second actual service-detail variation'],['service-movement','Movement & mobility','Third service-detail variation'],
 ['charlie','Meet Charlie','Practitioner profile and approach'],['clinic','The clinic','Location, access and contact entry'],['online','Online consultation','Human video appointment explanation'],
 ['programmes','Recovery programmes','Public R2 catalogue, explicitly a future feature'],['programme','Programme detail','Preview, curriculum, access terms'],['programme-checkout','Checkout handoff','Hosted-checkout transition, no fake card form'],['programme-pending','Purchase pending','Payment verification is not success'],['programme-complete','Purchase confirmation','Synthetic confirmation only; no private player'],
 ['faq','Frequently asked questions','Open accordion and categories'],['contact','Contact','Minimal non-clinical contact form'],['contact-sent','Message confirmation','Clearly simulated, nothing sent'],
 ['book','Book · time','Visit type, mode, date and time'],['book-loading','Book · loading','Unavailable data cannot be confirmed'],['book-online','Book · online','Same flow with online mode selected'],['book-empty','Book · no availability','No slots, change day, contact'],['book-details','Book · your details','Minimal fields, no symptom questionnaire'],['book-details-error','Book · validation','Visible associated field error'],['book-verify','Book · verify email','Single pasteable code field'],['book-review','Book · review','Authoritative summary pattern'],['book-conflict','Book · slot conflict','Retain details and select a different slot'],['book-success','Book · confirmation','Example persisted-result layout'],
 ['sign-in','Account entry only','Public gateway, not a patient dashboard'],['verify','Email verification','Public identity boundary only'],['verify-error','Verification error','Invalid/expired-code recovery'],
 ['menu','Expanded menu','Public navigation; no competing dock'],['search','Search results','Matching services with safe local search'],['search-empty','No search results','Reset and first-appointment route'],
 ['privacy','Privacy notice','Legal reading template, review required'],['terms','Terms','Legal reading template'],['cancellation','Cancellation policy','Policy reading template'],['accessibility','Accessibility','Honest accessibility statement template'],['cookies','Cookie preferences','Necessary-only default; optional controls'],
 ['not-found','404','Return home or find a service'],['unavailable','Service unavailable','No pretend success or fake availability'],['offline','Connection lost','Retry without losing booking choices']
];
const nav = () => `<header class="header container">${logo()}<nav class="desktop-nav" aria-label="Primary"><a href="#/services">Services</a><a href="#/charlie">Meet Charlie</a><a href="#/clinic">The clinic</a><a href="#/programmes">Programmes</a><a href="#/online">Online care</a>${btn('Book a visit','book')}</nav><a class="menu-button" href="#/menu" aria-label="Open navigation menu">${icon('menu')}</a></header>`;
function dock(){
 const active = currentRoute.startsWith('book') ? 'book' : currentRoute === 'online' ? 'online' : ['sign-in','verify','verify-error'].includes(currentRoute) ? 'sign-in' : 'home';
 return `<nav class="dock" aria-label="Primary mobile">${[['home','Home','home'],['book','Book','calendar'],['online','Online','video'],['sign-in','Account','user']].map(([r,t,i])=>`<a href="#/${r}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav>`;
}
const footer = () => `<footer class="footer"><div class="container"><div class="footer-brand">${logo()}<a class="text-link" href="#/screens">Design index ${icon('arrow')}</a></div><div class="footer-links">${[['services','Services'],['charlie','Meet Charlie'],['clinic','The clinic'],['contact','Contact'],['faq','FAQ'],['privacy','Privacy'],['terms','Terms'],['cancellation','Cancellation'],['accessibility','Accessibility'],['cookies','Cookies']].map(([r,t])=>`<a href="#/${r}">${t}</a>`).join('')}</div><p class="small">Design prototype · not a live clinic service. Imagery is illustrative, not Charlie’s real portrait. Services, reviews, prices, programmes and business details need owner approval. Nothing is booked, sent or purchased here.</p></div></footer>`;
const finder = (value = '', context = 'search') => `<form class="finder" data-form="search" data-context="${context}" role="search"><label class="sr-only" for="finder-input">Find a service or body area</label>${icon('search')}<input id="finder-input" name="query" placeholder="Search body area or service" value="${escapeHTML(value)}" autocomplete="off" maxlength="80"><button aria-label="Search services" type="submit">${icon('arrow')}</button></form>`;
const serviceCard = s => `<a class="service-card" href="#/service-${s.id}">${photo(s.asset,'service-photo',`Illustrative ${s.short.toLowerCase()} artwork`)}<div class="card-copy"><span class="card-arrow">${icon('arrow')}</span><h3>${s.short}</h3><p>${s.copy}</p></div></a>`;
const serviceRow = s => `<a class="service-row" href="#/service-${s.id}">${photo(s.asset,'',`Illustrative ${s.short.toLowerCase()} artwork`)}<div><h3>${s.name}</h3><p>${s.copy}</p><span class="text-link">Explore care ${icon('arrow')}</span></div></a>`;
const faqItems = [
 ['Do I need to know which treatment to book?','No. The first-appointment option is designed as a starting point when you are unsure. Charlie will need to assess your situation before deciding on suitable care.'],
 ['What happens at my first appointment?','The proposed visit starts with a conversation and movement assessment, followed by a discussion of possible next steps. The exact format and duration need clinic approval.'],
 ['What should I bring?','The clinic will provide preparation instructions with your appointment. Relevant referral or scan reports may be useful; please do not upload them through the public contact form.'],
 ['Can my appointment be online?','The online-care page explains the proposed video visit. Suitability must be confirmed by the clinician. Online booking stays hidden in production until the service is ready.'],
 ['Can I change or cancel an appointment?','The final notice period and any charges will appear before confirmation. These policies have not yet been approved for this prototype.'],
 ['Where is the clinic?','The address, access information and directions are awaiting owner confirmation. No city or street in an earlier mockup should be treated as real.']
];
const faq = (items = faqItems, openFirst = false) => items.map(([q,a],i)=>`<details class="faq-item" ${openFirst&&i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('');
function home(){return `<main id="main"><div class="container"><section class="hero"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">Care that starts with you</div><h1>Expert care for<br>a stronger you.</h1><p class="intro">Physiotherapy in clinic and online.</p></div><div class="hero-person"><b>Meet Charlie</b><span>A personal approach<br>to your next step.</span></div>${photo('portrait','hero-portrait','Illustrative practitioner portrait — replace with Charlie’s approved photograph')}</div>${finder()}<div class="actions">${btn('Book a visit','book','','calendar')}${btn('Online visit','online','secondary','video')}</div><div class="chips issue-row" aria-label="Browse by body area">${['Back','Neck','Shoulder','Knee'].map(x=>`<a class="chip" href="#/search?area=${x.toLowerCase()}">${x}</a>`).join('')}<a class="chip" href="#/services">All areas</a></div></section><section class="section"><div class="section-head"><h2>How we can help</h2>${textLink('View all','services')}</div><div class="service-rail">${services.map(serviceCard).join('')}</div></section></div><section class="charlie-section"><div class="container charlie-grid">${photo('portrait','','Illustrative practitioner portrait')}<div><div class="eyebrow">Your physiotherapist</div><h2>Hi, I’m Charlie.</h2><p>Care begins with listening. Let’s understand your movement and find your next step.</p>${textLink('Get to know Charlie','charlie')}</div></div></section><section class="story-band" aria-label="Patient story design example"><div class="container"><div class="eyebrow">Patient stories · illustrative copy</div><div class="quote-mark" aria-hidden="true">“</div><blockquote>I felt listened to.<br>And clear about what came next.</blockquote><span class="story-source">Example testimonial layout — not a real patient review</span><p class="small">Publish this section only with an approved, genuine story.</p></div></section><div class="container section home-bottom"><div class="clinic-preview">${icon('pin')}<div><div class="eyebrow">Visit PhysiX</div><h3>A space for your next step.</h3><p>Find practical clinic information before your visit.</p>${textLink('Explore the clinic','clinic')}</div></div><a class="programme-teaser" href="#/programmes">${photo('movement','','Illustrative movement programme artwork')}<div><span class="inline-label">COMING LATER · PREVIEW</span><h3>Keep moving at home.</h3><p>Explore the planned guided-programme experience.</p><span class="text-link">View programmes ${icon('arrow')}</span></div></a></div></main>`;}
function serviceListing(q = '', empty = false){
 const results = empty ? [] : services.filter(s=>(activeFilter==='All'||s.group===activeFilter) && `${s.name} ${s.copy} ${s.area}`.toLowerCase().includes(q.toLowerCase()));
 return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">Find your starting point</div><h1>Care for the way<br>you want to move.</h1><p>Explore the proposed PhysiX services.</p>${finder(q,'services')}<div class="chips" aria-label="Service categories">${['All','Pain & movement','Rehabilitation'].map(x=>`<button type="button" class="chip" data-filter="${x}" aria-pressed="${activeFilter===x}">${x}</button>`).join('')}</div></div><p class="count">${results.length} services${q?` matching “${escapeHTML(q)}”`:''}</p>${results.length?`<div class="service-list">${results.map(serviceRow).join('')}</div>`:emptyState('No matching services','Try a body area such as back or knee, or browse all services.','Reset search','services')}<section class="section"><div class="offering"><h2>Not sure where to start?</h2><p style="margin:12px 0 20px">Choose a first appointment. You do not need to select a treatment yourself.</p>${btn('Book a first appointment','book')}</div></section></main>`;
}
function serviceDetail(id){const s=services.find(x=>x.id===id)||services[0];return `<main id="main" class="container"><a class="back-link" href="#/services">${icon('back')}All services</a><div class="detail-layout section"><div>${photo(s.asset,'detail-media',`Illustrative ${s.name.toLowerCase()} artwork`)}<div class="detail-title"><div class="eyebrow">Proposed service · clinician review required</div><h1>${s.name}</h1><p>${s.intro}</p></div><section class="section"><h2>What to expect</h2>${stepList([['Start with your story','Discuss what matters to you and what you would like to get back to.'],['Understand your movement','Your physiotherapist assesses your situation before recommending an approach.'],['Agree your next step','Leave with an explanation of the proposed care and follow-up.']])}</section><section><h2>Questions about this visit</h2>${faq(faqItems.slice(0,3),true)}</section></div><aside class="offering"><div class="eyebrow">Start with an assessment</div><h2>Your first visit</h2><p style="margin:14px 0">A clear starting point, without choosing a technical treatment.</p><div class="meta-row"><span>Appointment</span><strong>First assessment</strong></div><div class="meta-row"><span>Clinician</span><strong>Charlie</strong></div><div class="meta-row"><span>Fee & duration</span><strong>To be confirmed</strong></div><div style="margin-top:20px">${btn('Find an appointment',`book?service=${id}`,'wide')}</div><span class="note">Live fees and duration must be shown before a real booking.</span></aside></div></main>`;}
function charliePage(){return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">The person behind your care</div><h1>Meet Charlie.</h1></div><section class="profile-hero">${photo('portrait','','Illustrative portrait, not Charlie’s real photograph')}<div><div class="eyebrow">PhysiX · practitioner profile concept</div><h2>A person-first<br>approach to movement.</h2><p style="margin:18px 0 24px">Space for Charlie’s own introduction: his approach, experience and the people he works with. Keep it personal, specific and easy to read.</p>${btn('Book with Charlie','book')}</div></section><section class="section"><h2>Care, built around you.</h2><div class="approach-grid" style="margin-top:28px"><div><h3>Listen first.</h3><p>Understand your story and what you want to do more comfortably.</p></div><div><h3>Explain clearly.</h3><p>Talk through the assessment and possible next steps in everyday language.</p></div><div><h3>Move forward.</h3><p>Agree a plan with the clinician, then review it as your needs change.</p></div></div></section><div class="two-col"><section><h2>Experience & education</h2><p style="margin-top:16px">Verified qualifications and professional experience will appear here. No placeholder awards, patient totals or ratings.</p><div class="notice" style="margin-top:20px">Content required: full professional name, permitted title, qualifications, registration where relevant, and approved portrait.</div></section><section><h2>Meet before you visit</h2><p style="margin:16px 0 20px">A short introduction video can live here once recorded and approved. It will never autoplay.</p>${btn('Explore the clinic','clinic','secondary')}</section></div></main>`;}
function clinicPage(){return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">In-person care</div><h1>Your visit,<br>made simpler.</h1><p>Practical information before you arrive.</p></div><div class="two-col"><div><div class="map-art" role="img" aria-label="Illustrated location placeholder; not an actual map"><span class="map-pin">${icon('pin')}</span><span class="map-label">Illustration · address not yet supplied</span></div><div class="section"><h2>Find PhysiX</h2><p style="margin:14px 0">Clinic city, street address and entrance details are awaiting confirmation.</p><button class="button secondary wide" disabled>Directions available after address approval</button><span class="note">No external map is loaded in this prototype.</span></div></div><div class="stack"><section class="offering"><div class="eyebrow">Before you come</div><h2>Know what to expect.</h2>${checkList(['Book an appointment before visiting.','Check the confirmed location and preparation details.','Contact the clinic about access requirements.'])}</section><div class="summary-list"><div class="meta-row"><span>Opening hours</span><strong>To be confirmed</strong></div><div class="meta-row"><span>Step-free access</span><strong>To be verified</strong></div><div class="meta-row"><span>Parking & transport</span><strong>Details pending</strong></div></div><div class="actions">${btn('Book a visit','book')}${btn('Contact PhysiX','contact','secondary')}</div></div></div><section class="section"><h2>Useful before your first visit</h2>${faq([faqItems[2],faqItems[5]],true)}</section></main>`;}
function onlinePage(){return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">Human care, wherever you are</div><h1>Your physiotherapist.<br>A video call away.</h1><p>A proposed online appointment with Charlie — not an AI impersonation or an automated diagnosis.</p></div><div class="two-col"><section class="profile-hero" style="display:block">${photo('portrait','','Illustrative practitioner portrait')}<div style="margin-top:24px"><div class="pill">Human video appointment</div><h2 style="margin:16px 0">Start with a conversation.</h2><p>Discuss your situation and whether an online assessment is appropriate.</p></div></section><section><h2>How an online visit works</h2>${stepList([['Choose a time','Use the same clear booking flow as an in-clinic visit.'],['Join your appointment','A private joining link is available to the confirmed patient.'],['Discuss your next steps','Your clinician explains the findings and any recommended follow-up.']])}<div class="actions" style="margin-top:28px">${btn('Book online consultation','book-online','','video')}</div><span class="note">Design preview. Offer stays hidden until online-care operations and suitability rules are approved.</span><div class="notice" style="margin-top:22px">Online care is not an emergency service. Some concerns need an in-person assessment.</div></section></div><section class="section"><h2>Good to know</h2>${faq([faqItems[3],['What will I need?','A private space, a reliable connection and a device with a camera. Confirmed preparation instructions must come from the clinic.']],true)}</section></main>`;}
function programmesPage(){return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">R2 · future public catalogue</div><h1>More movement.<br>At your own pace.</h1><p>Educational programmes to explore at home. Not a replacement for an individual assessment.</p></div><div class="programme-grid">${[['Everyday mobility','movement','Simple routines, clearly explained.'],['Back-care foundations','manual','Understand everyday movement habits.'],['Return to activity','sports','Explore a more gradual approach.']].map(([n,a,c],i)=>`<a class="service-card programme-card" href="#/programme">${photo(a,'service-photo','Illustrative programme artwork')}<div class="card-copy"><div class="eyebrow">Programme concept ${i+1}</div><h3>${n}</h3><p>${c}</p><span class="text-link">Preview programme ${icon('arrow')}</span></div></a>`).join('')}</div><div class="notice" style="margin-top:28px">Future-feature design, not products currently for sale. Programme content, authorship, suitability, prices and access terms require approval.</div><section class="section"><h2>Need personal guidance?</h2><p style="margin:14px 0 22px">Start with a clinician rather than selecting exercises based on a diagnosis you have made yourself.</p>${btn('Explore appointments','book')}</section></main>`;}
function programmePage(){return `<main id="main" class="container"><a class="back-link" href="#/programmes">${icon('back')}All programmes</a><div class="detail-layout section"><div>${photo('movement','detail-media','Illustrative movement programme artwork')}<div class="detail-title"><div class="eyebrow">Educational programme · concept</div><h1>Everyday mobility.</h1><p>A calm, guided introduction to making movement part of your day.</p></div><section class="section"><h2>Inside the programme</h2>${[['01','Getting started','Preview'],['02','Movement foundations','Video lesson'],['03','Building a routine','Video lesson'],['04','Your next steps','Guide']].map(([n,t,l])=>`<div class="lesson-row"><strong>${n} &nbsp; ${t}</strong><span>${l}</span></div>`).join('')}<span class="note">Curriculum structure is illustrative; no exercise instructions have been published.</span></section><h2>Before you choose</h2>${faq([['Is this an individual recovery plan?','No. This public catalogue is for educational content. Clinician-assigned care is a separate, private product and is outside this design package.'],['How long will I have access?','The approved access period, support scope and refund terms must appear here and at checkout before a real sale.']],true)}</div><aside class="offering"><div class="eyebrow">Example offer · not for sale</div><div class="price">€49 <small>sample price</small></div><p style="margin-top:10px">One-time purchase layout</p>${checkList(['Guided lesson structure','Accessible video and written content','Clear access and support terms'])}<div style="margin-top:24px">${btn('Preview purchase flow','programme-checkout','wide')}</div><span class="note">No payment is collected. This button opens a design of the provider handoff.</span></aside></div></main>`;}
function emptyState(h,p,label,r){return `<div class="empty">${icon('search')}<h2>${h}</h2><p>${p}</p>${btn(label,r,'secondary')}</div>`;}
function faqPage(){return `<main id="main" class="container legal"><div class="page-head"><div class="eyebrow">A little clarity before you book</div><h1>Good questions.<br>Clear next steps.</h1><p>Practical information for your first visit.</p></div><div class="chips"><a class="chip active" href="#first-visit">First visit</a><a class="chip" href="#booking-faq">Booking</a><a class="chip" href="#online-faq">Online care</a></div><section class="faq-group" id="first-visit"><h2>Your first visit</h2>${faq(faqItems.slice(0,3),true)}</section><section class="faq-group" id="booking-faq"><h2>Booking & the clinic</h2>${faq(faqItems.slice(4))}</section><section class="faq-group" id="online-faq"><h2>Online care</h2>${faq([faqItems[3]])}</section><div class="offering"><h3>Still have a question?</h3><p style="margin-top:12px">Ask the clinic about an appointment or practical arrangements.</p>${textLink('Contact PhysiX','contact')}</div></main>`;}
const visitLabel = () => booking.type==='first'?'First appointment':'Follow-up appointment';
const modeLabel = () => booking.mode==='online'?'Online consultation':'In-clinic visit';
const sampleSummary = () => `<div class="selection-summary">${icon(booking.mode==='online'?'video':'calendar')}<div><strong>${visitLabel()} · ${modeLabel()}</strong><p>September ${booking.date}, 2026 · ${booking.time} · Europe/Sofia</p><p>Example: 45 minutes · €65</p></div></div>`;
const flowTop = (step,title,intro) => `<div class="flow-topline"><span>Step ${step} of 3</span><span>Design preview</span></div><div class="progress" aria-label="Step ${step} of 3">${[1,2,3].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="flow-title"><h1>${title}</h1><p>${intro}</p></div>`;
function loadingPage(isBooking = false){return isBooking ? `${flowTop(1,'Finding available times.','Please wait while the latest availability is checked.')}<div role="status" class="skeleton-stack" aria-label="Loading appointment times"><div class="skeleton"></div><div class="skeleton short"></div><div class="loading-slots">${Array(9).fill('<div class="skeleton"></div>').join('')}</div><p class="small">No date or appointment is selected yet.</p></div>` : `<main id="main" class="container"><div class="page-head"><div class="eyebrow">Find your starting point</div><h1>Our services.</h1><p role="status">Loading service information…</p></div><div class="skeleton-stack" aria-hidden="true">${Array(3).fill('<div class="skeleton-row"><div class="skeleton-image"></div><div><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div></div></div>').join('')}</div></main>`;}
function bookingTime(empty = false){return `${flowTop(1,'Find your next appointment.','Choose your visit and a time that works for you.')}<div class="flow-section"><h2>Your visit</h2><div class="choices"><label class="choice"><input type="radio" name="visit-type" value="first" ${booking.type==='first'?'checked':''}><span><b>First appointment</b><small>New to PhysiX or not sure where to start.</small></span></label><label class="choice"><input type="radio" name="visit-type" value="follow-up" ${booking.type==='follow-up'?'checked':''}><span><b>Follow-up</b><small>Continue care already agreed with your clinician.</small></span></label></div></div><div class="flow-section"><h2>Where would you like to meet?</h2><div class="choices two"><label class="choice"><input type="radio" name="visit-mode" value="clinic" ${booking.mode==='clinic'?'checked':''}><span><b>In clinic</b><small>Visit PhysiX</small></span></label><label class="choice"><input type="radio" name="visit-mode" value="online" ${booking.mode==='online'?'checked':''}><span><b>Online</b><small>Video appointment</small></span></label></div></div><div class="flow-section"><div class="date-heading"><h2 style="margin:0">Choose a date</h2><strong>September 2026</strong></div><div class="dates">${[['Mon','14'],['Tue','15'],['Wed','16'],['Thu','17'],['Fri','18']].map(([d,n])=>`<button class="date" data-date="${n}" aria-pressed="${booking.date===n}"><span>${d}</span><b>${n}</b><span>Sep</span></button>`).join('')}</div><span class="note">Example dates. Live availability is not connected.</span></div><div class="flow-section"><h2>Available times</h2>${empty?emptyState('No times on this day','Choose another day or ask the clinic for help.','Try another day','book'):`<div class="times">${['09:00','09:45','10:00','11:15','13:00','14:30','15:15','16:00'].map((t,i)=>`<button class="time" data-time="${t}" ${i===1?'disabled':''} aria-pressed="${booking.time===t}">${t}</button>`).join('')}</div><span class="note">Times shown in Europe/Sofia. Your selection is not held.</span>`}</div>${sampleSummary()}`;}
function bookingDetails(error = false){return `${flowTop(2,'A few details about you.','No account setup before you can see appointment times.')}${sampleSummary()}<form id="details-form" data-form="details" novalidate><label class="field"><span>Full name</span><input name="name" autocomplete="name" required maxlength="100" value="${escapeHTML(booking.name)}" ${error?'aria-invalid="true" aria-describedby="name-error"':''}>${error?'<span class="error-message" id="name-error">Enter your full name so the clinic can identify your booking.</span>':''}</label><label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" inputmode="email" required maxlength="160" value="${escapeHTML(booking.email)}"><small>Used for verification and appointment information.</small></label><label class="field"><span>Phone number <small style="display:inline;font-weight:400">(optional)</small></span><input name="phone" type="tel" autocomplete="tel" inputmode="tel" maxlength="30" value="${escapeHTML(booking.phone)}"></label><label class="checkbox"><input type="checkbox" name="terms" required><span>I have read the <a href="#/cancellation">cancellation policy</a> and <a href="#/privacy">privacy notice</a>. Final reviewed terms must replace these drafts.</span></label><div class="notice">Prototype only. Details remain in this page’s memory. No email, appointment or account is created.</div></form>`;}
function verification(isBooking = false, error = false){return `${isBooking?flowTop(2,'Check your email.','Verification keeps your appointment linked to you.'):'<div class="eyebrow">Account entry · public boundary</div><h1>Check your email.</h1><p style="margin-top:14px">Enter the code sent to your email address.</p>'}<div class="notice" style="margin:22px 0">No email was sent. Enter any six digits to explore this design.</div><p class="small">Example recipient: ${escapeHTML(booking.email||'you@example.com')}</p><form id="verify-form" data-form="verify" data-booking="${isBooking}"><label class="field"><span>Six-digit code</span><input class="otp" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required placeholder="000000" aria-describedby="code-help" ${error?'aria-invalid="true"':''}><small id="code-help" class="${error?'error-message':''}">${error?'This example code has expired. Request a new code or edit your email.':'You can paste the whole code into this field.'}</small></label>${!isBooking?'<button class="button wide" type="submit">Continue '+icon('arrow')+'</button>':''}</form><button class="button secondary wide" style="margin-top:14px" data-action="resend">Resend code (preview)</button>${textLink('Use a different email',isBooking?'book-details':'sign-in')}`;}
function review(){return `${flowTop(3,'Everything look right?','Review your appointment before the final confirmation.')}<div class="summary-list">${[['Appointment',visitLabel()],['Where',modeLabel()],['Clinician','Charlie'],['Date',`September ${booking.date}, 2026`],['Time',`${booking.time} · Europe/Sofia`],['Duration','45 minutes · example'],['Price','€65 · example'],['Name',booking.name||'Example patient'],['Email',booking.email||'you@example.com']].map(([a,b])=>`<div class="meta-row"><span>${a}</span><strong>${escapeHTML(b)}</strong></div>`).join('')}</div><div class="actions">${btn('Edit time','book','secondary')}${btn('Edit details','book-details','secondary')}</div><div class="notice" style="margin-top:24px">The approved cancellation terms and payment timing must appear here. No cancellation period or “free cancellation” claim has been invented.</div><span class="note">In the real service, confirmation requires a successful server booking. A selected time alone is not an appointment.</span>`;}
function bookingSuccess(){return `<div class="state-page"><div class="state-icon">${icon('check')}</div><div class="eyebrow">Sample confirmation</div><h1>You’re all set.</h1><p>Your confirmed-appointment screen would show the information below.</p><div style="margin:26px 0">${sampleSummary()}</div><div class="notice">This is a visual example. No appointment has been created and no confirmation email has been sent.</div><div class="actions">${btn('Back to home','home')}${btn('Clinic information','clinic','secondary')}</div><span class="note">The live confirmation is visible only to the authenticated booking owner. No private account screens are included in this package.</span></div>`;}
function conflict(){return `<div class="state-page"><div class="state-icon">${icon('clock')}</div><div class="eyebrow">Availability changed</div><h1>That time just<br>became unavailable.</h1><p>Your details are still here. Choose another time to continue; nothing has been booked.</p><div style="margin:24px 0">${sampleSummary()}</div><div class="actions">${btn('Choose another time','book')}${btn('Contact the clinic','contact','secondary')}</div></div>`;}
function signIn(){return `<main id="main" class="container"><div class="auth-card"><div class="state-icon">${icon('user')}</div><div class="eyebrow">Your PhysiX account</div><h1>Your care.<br>One place.</h1><p>Sign in to manage appointments and access your care. This design stops before the logged-in area.</p><form data-form="sign-in"><label class="field"><span>Email address</span><input name="email" type="email" inputmode="email" autocomplete="email" required placeholder="you@example.com"></label><button class="button wide" type="submit">Continue with email ${icon('arrow')}</button></form><span class="note">No password or registration wall before browsing and booking. Prototype: no email is sent.</span>${textLink('Keep exploring PhysiX','home')}</div></main>`;}
function menuPage(){return `<div class="menu-page"><header class="header container">${logo()}<a class="menu-button" style="display:grid" href="#/${lastPublicRoute}" aria-label="Close menu">${icon('close')}</a></header><main id="main" class="container"><div class="menu-content"><div class="menu-links">${[['home','Home'],['services','Services'],['charlie','Meet Charlie'],['online','Online consultation'],['programmes','Recovery programmes'],['clinic','The clinic'],['faq','Questions & answers'],['contact','Contact']].map(([r,t],i)=>`<a href="#/${r}"><span>${t}</span><small>${String(i+1).padStart(2,'0')}</small></a>`).join('')}</div><div class="actions">${btn('Book a visit','book','white')}${btn('My account','sign-in','secondary')}</div><div class="menu-meta"><a href="#/screens">Design index</a><span style="align-self:center">EN · BG translation pending</span></div></div></main></div>`;}
function searchPage(q = 'back',empty = false){const results=empty?[]:services.filter(s=>`${s.name} ${s.area}`.toLowerCase().includes(q.toLowerCase()));return `<main id="main" class="container search-page"><a class="back-link" href="#/home">${icon('back')}Home</a><div class="page-head"><div class="eyebrow">Find a service</div><h1>Let’s find your<br>starting point.</h1>${finder(q)}</div>${results.length?`<p class="count">${results.length} services matching “${escapeHTML(q)}”</p><div class="service-list">${results.map(serviceRow).join('')}</div>`:emptyState('No matches yet','Try a different body area, or view all of the available services.','View all services','services')}<section class="section"><h2>You don’t need a diagnosis to book.</h2><p style="margin:14px 0 22px">Choose a first appointment and discuss your situation with the clinician.</p>${btn('Book a first appointment','book')}</section></main>`;}
function contactPage(){return `<main id="main" class="container"><div class="page-head"><div class="eyebrow">A practical question?</div><h1>Let’s get you<br>to the right place.</h1><p>For booking, clinic access or general enquiries.</p></div><div class="two-col"><section><div class="offering"><h2>Ready for an appointment?</h2><p style="margin:16px 0 22px">The booking flow is the quickest way to explore appointment options.</p>${btn('Find a time','book')}</div><div class="summary-list"><div class="meta-row"><span>Email</span><strong>To be supplied</strong></div><div class="meta-row"><span>Phone</span><strong>To be supplied</strong></div><div class="meta-row"><span>Response time</span><strong>To be confirmed</strong></div></div><p class="small">No invented phone number, address or support guarantee. This form is not an emergency or clinical-advice channel.</p></section><form data-form="contact"><label class="field" style="margin-top:0"><span>Your name</span><input name="name" autocomplete="name" maxlength="100" required></label><label class="field"><span>Email</span><input name="email" type="email" autocomplete="email" required></label><label class="field"><span>How can we help?</span><textarea name="message" maxlength="1000" required aria-describedby="contact-help" placeholder="Ask about a visit or the clinic"></textarea><small id="contact-help">Please do not include medical records, symptoms, identification numbers or sensitive health details.</small></label><p class="small">Read the <a href="#/privacy" style="text-decoration:underline">privacy notice</a> before sending. Prototype submissions are not transmitted or stored.</p><button class="button wide" style="margin-top:20px" type="submit">Preview message confirmation ${icon('arrow')}</button></form></div></main>`;}
const legalData = {
 privacy:['Privacy notice','How information should be handled.',[['Who is responsible?','The clinic’s legal entity, controller contact and supervisory-authority information must be supplied and reviewed.'],['What information is used?','The approved notice must explain booking, communication, account and any health-data processing separately, including lawful bases, recipients and retention.'],['Your choices and rights','The final notice must explain applicable rights, how to make a request, identity checks and how complaints are handled.'],['Providers and international transfers','List only the providers actually used, with reviewed contractual, location and transfer information.']]],
 terms:['Terms of service','Clear expectations, before you proceed.',[['About PhysiX','Insert the correct business identity, professional details, contact information and the services actually offered.'],['Booking and payment','Explain when an appointment is confirmed, which fees apply, when payment is due, and how errors or cancellations are handled.'],['Online services and educational content','State the approved service scope and limitations. Educational programmes are separate from individual clinical care.'],['Support and complaints','Provide the real support process, applicable consumer information and reviewed legal terms.']]],
 cancellation:['Cancellation & changes','Know where you stand before booking.',[['Changing an appointment','The actual notice period, process and conditions have not been approved. Do not substitute a generic 24-hour policy.'],['Cancelling an appointment','Specify the real fees or refunds, exceptions, no-show handling and contact method before live booking is enabled.'],['When PhysiX needs to change a visit','Explain how the clinic contacts the patient and handles a replacement appointment or refund.']]],
 accessibility:['Accessibility','A service that is easier to use.',[['Our design target','The interface is designed toward WCAG 2.2 AA. This prototype is not a compliance certification.'],['Known limitations','English reference screens, illustrative media and draft content are included. Real-device, assistive-technology, Bulgarian-copy and full accessibility audits remain necessary.'],['Need assistance?','Publish the clinic’s verified contact method and a practical route for people who cannot use online booking.']]]
};
function legalPage(id){const [h,sub,parts]=legalData[id];return `<main id="main" class="container legal"><div class="page-head"><div class="eyebrow">PhysiX · information</div><h1>${h}</h1><p>${sub}</p></div>${notice('Layout and content requirements only. This is not a reviewed legal policy and must not be published as one.')}<nav class="policy-tabs" aria-label="Information pages">${Object.entries(legalData).map(([r,[t]])=>`<a class="chip ${r===id?'active':''}" href="#/${r}">${t}</a>`).join('')}</nav><p class="small">Draft · owner and appropriate professional review required</p>${parts.map(([t,p],i)=>`<section><h2>${i+1}. ${t}</h2><p>${p}</p></section>`).join('')}<section><h2>Questions?</h2>${textLink('Contact PhysiX','contact')}</section></main>`;}
function cookiesPage(){return `<main id="main" class="container legal"><div class="page-head"><div class="eyebrow">Your preferences</div><h1>Only what<br>you choose.</h1><p>Optional categories stay off unless you enable them.</p></div><form data-form="cookies"><div class="toggle-row"><div><strong>Necessary</strong><p>Required for core functionality in the live service.</p></div><span class="pill">Always on</span></div><label class="toggle-row"><span><strong>Analytics</strong><p>Optional usage measurement, only after the provider and consent setup are approved.</p></span><input name="analytics" type="checkbox" aria-label="Allow analytics"></label><label class="toggle-row"><span><strong>Marketing</strong><p>No advertising tools are present in this prototype.</p></span><input name="marketing" type="checkbox" aria-label="Allow marketing"></label><div class="actions" style="margin-top:24px"><button type="submit" class="button">Save preferences</button><button type="button" class="button secondary" data-action="reject-cookies">Reject optional</button></div></form><div id="cookie-status" role="status" class="note">Prototype only: controls do not activate tracking. No cookie banner is needed in production if no optional tools are used.</div></main>`;}
function genericState(kind){const data={
 'not-found':['404','This page took<br>a different path.','Let’s get you back to the care you were looking for.','Back to home','home'],
 unavailable:['refresh','We can’t load<br>this right now.','We cannot show reliable availability. Nothing has been booked. Please try again or contact the clinic.','Try again','book'],
 offline:['wifi','Let’s reconnect.','Your current choices remain in this prototype’s memory. Restore your connection before continuing.','Try again','book'],
 'contact-sent':['mail','Message confirmation.','This is where a successful message would be acknowledged. This prototype has not sent or stored your message.','Back to home','home'],
 'programme-checkout':['lock','Continue to<br>secure checkout.','The live service would transfer you to the approved payment provider. No card fields or payment processing are simulated here.','Preview pending state','programme-pending'],
 'programme-pending':['clock','Checking your<br>purchase status.','A redirect is not proof of payment. The live service waits for verified payment confirmation before granting access.','Preview confirmation','programme-complete'],
 'programme-complete':['check','Purchase confirmation.','Sample only. No payment was made, no entitlement was granted and no private programme player is included.','Back to programmes','programmes']
 };const [i,h,p,t,r]=data[kind]||data['not-found'];return `<main id="main" class="container"><div class="state-page center">${i==='404'?'<div class="error-number">404</div>':`<div class="state-icon">${icon(i)}</div>`}<div class="eyebrow">${kind.startsWith('programme')?'Future commerce · design preview':'PhysiX · public website'}</div><h1>${h}</h1><p>${p}</p><div class="actions">${btn(t,r)}${btn('Contact PhysiX','contact','secondary')}</div></div></main>`;}
function screenIndex(){return `<main id="main" class="container screen-index"><div class="eyebrow">Public website · visual handoff v2</div><h1>Every public screen.<br>One design language.</h1><p>These are interactive design references, not the implemented PhysiX product. No Gymaf, dashboard, exercise player or staff UI is included.</p><div class="notice" style="margin-top:22px">All content, prices and people are illustrative or explicitly awaiting approval. Use this index to inspect the complete visitor experience.</div><div class="screen-grid">${screenList.map(([r,t,s],i)=>`<a class="screen-tile" href="#/${r}"><div><strong>${String(i+1).padStart(2,'0')} · ${t}</strong><small>${s}</small></div>${icon('arrow')}</a>`).join('')}</div></main>`;}
function flowPage(route){
 let inner='',step=1,back='home',cta='',action='';
 if(route==='book-loading'){inner=loadingPage(true);cta='Loading availability';action='loading-disabled';}
 else if(['book','book-online','book-empty'].includes(route)){if(route==='book-online')booking.mode='online';inner=bookingTime(route==='book-empty');cta=route==='book-empty'?'Try another day':'Continue';action=route==='book-empty'?'book':'book-details';}
 else if(['book-details','book-details-error'].includes(route)){inner=bookingDetails(route.endsWith('error'));step=2;back='book';cta='Continue to verification';action='submit-details';}
 else if(route==='book-verify'){inner=verification(true);step=2;back='book-details';cta='Verify & review';action='submit-code';}
 else if(route==='book-review'){inner=review();step=3;back='book-details';cta='Preview confirmation';action='book-success';}
 else if(route==='book-conflict'){inner=conflict();step=3;back='book';}
 else if(route==='book-success'){inner=bookingSuccess();step=3;back='home';}
 else {inner='<div class="state-page"><h1>Booking step not found.</h1>'+btn('Start a booking','book')+'</div>';}
 return `<div class="flow-shell"><header class="flow-header container"><a class="back-link" href="#/${back}">${icon('back')}Back</a>${logo()}</header><main id="main" class="container flow-main">${inner}</main>${cta?`<div class="flow-action"><div class="flow-action-inner"><button class="button wide" data-action="${action}" ${action==='loading-disabled'?'disabled':''}>${cta}${icon('arrow')}</button><div class="small">Design preview · no real appointment will be created</div></div></div>`:''}</div>`;
}
function render(){
 const hash=location.hash.slice(1)||'/home';
 if(!hash.startsWith('/'))return; // Local FAQ anchors keep the current page.
 const previousRoute = currentRoute;
 const [path,qs='']=hash.slice(1).split('?');const params=new URLSearchParams(qs);currentRoute=path||'home';
 if(params.has('area') && ['back','neck','shoulder','knee'].includes(params.get('area'))) searchQuery=params.get('area');
 if(!['menu','search','search-empty','screens'].includes(currentRoute))lastPublicRoute=currentRoute;
 let html='',shell=true;
 if(currentRoute==='menu'){html=menuPage();shell=false;}
 else if(currentRoute.startsWith('book')){html=flowPage(currentRoute);shell=false;}
 else if(currentRoute==='home')html=home();
 else if(currentRoute==='services')html=serviceListing(serviceQuery);
 else if(currentRoute==='services-loading')html=loadingPage();
 else if(currentRoute.startsWith('service-'))html=serviceDetail(currentRoute.replace('service-',''));
 else if(currentRoute==='charlie')html=charliePage();
 else if(currentRoute==='clinic')html=clinicPage();
 else if(currentRoute==='online')html=onlinePage();
 else if(currentRoute==='programmes')html=programmesPage();
 else if(currentRoute==='programme')html=programmePage();
 else if(currentRoute==='faq')html=faqPage();
 else if(currentRoute==='contact')html=contactPage();
 else if(currentRoute==='sign-in')html=signIn();
 else if(currentRoute==='verify'||currentRoute==='verify-error')html=`<main id="main" class="container"><div class="auth-card">${verification(false,currentRoute==='verify-error')}</div></main>`;
 else if(currentRoute==='search'||currentRoute==='search-empty')html=searchPage(currentRoute==='search-empty'?'no-match':searchQuery,currentRoute==='search-empty');
 else if(legalData[currentRoute])html=legalPage(currentRoute);
 else if(currentRoute==='cookies')html=cookiesPage();
 else if(currentRoute==='screens')html=screenIndex();
 else html=genericState(currentRoute);
 $('#app').innerHTML=shell?nav()+html+footer()+dock():html;
 document.title=`PhysiX · ${screenList.find(x=>x[0]===currentRoute)?.[1]||'Design index'}`;
 document.body.dataset.route=currentRoute;
 window.scrollTo(0,0);
 if(currentRoute==='menu')$('.menu-page .menu-button')?.focus({preventScroll:true});
 if(currentRoute==='search')$('#finder-input')?.focus({preventScroll:true});
 if(previousRoute==='menu' && currentRoute!=='menu')$('.menu-button')?.focus({preventScroll:true});
 $('#announcement').textContent=document.title;
}
function go(r){if(location.hash==='/'+r||location.hash==='#/'+r){render();}else{location.hash='/'+r;}}
function refreshSummary(){const box=$('.selection-summary');if(box)box.outerHTML=sampleSummary();}
function announce(s){$('#announcement').textContent=s;}
function saveDetails(form){
 const inputs=[...form.querySelectorAll('input')];let ok=true;
 for(const input of inputs){if(!input.checkValidity()){input.setAttribute('aria-invalid','true');ok=false;}else input.removeAttribute('aria-invalid');}
 const name=form.elements.namedItem('name');if(!name.value.trim()){name.setAttribute('aria-invalid','true');ok=false;}
 if(!ok){let error=$('#form-error');if(!error){error=document.createElement('div');error.id='form-error';error.className='notice error';error.setAttribute('role','alert');form.prepend(error);}error.textContent='Please enter your name, a valid email and acknowledge the draft policies to continue this preview.';form.querySelector('[aria-invalid=true]')?.focus();return;}
 booking.name=name.value.trim();booking.email=form.elements.namedItem('email').value;booking.phone=form.elements.namedItem('phone').value;go('book-verify');
}
document.addEventListener('click',event=>{
 const filter=event.target.closest('[data-filter]');if(filter){const y=scrollY;activeFilter=filter.dataset.filter;render();window.scrollTo(0,y);document.querySelector('[data-filter="'+activeFilter+'"]')?.focus({preventScroll:true});return;}
 const date=event.target.closest('[data-date]');if(date){booking.date=date.dataset.date;document.querySelectorAll('[data-date]').forEach(x=>x.setAttribute('aria-pressed',String(x===date)));refreshSummary();return;}
 const time=event.target.closest('[data-time]');if(time&&!time.disabled){booking.time=time.dataset.time;document.querySelectorAll('[data-time]').forEach(x=>x.setAttribute('aria-pressed',String(x===time)));refreshSummary();return;}
 const action=event.target.closest('[data-action]');if(!action)return;
 const key=action.dataset.action;
 if(key==='submit-details'){saveDetails($('#details-form'));return;}
 if(key==='submit-code'){$('#verify-form').requestSubmit();return;}
 if(key==='resend'){announce('Preview only. No verification email was sent.');action.textContent='Preview only — no email sent';return;}
 if(key==='reject-cookies'){document.querySelectorAll('.toggle-row input').forEach(x=>x.checked=false);$('#cookie-status').textContent='Optional categories rejected in this preview. No trackers were enabled.';return;}
 go(key);
});
document.addEventListener('change',event=>{
 if(event.target.name==='visit-type'){booking.type=event.target.value;refreshSummary();}
 if(event.target.name==='visit-mode'){booking.mode=event.target.value;refreshSummary();}
});
document.addEventListener('submit',event=>{
 const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const data=new FormData(form);
 if(form.dataset.form==='search'){activeFilter='All';const q=String(data.get('query')||'').trim();if(form.dataset.context==='services'){serviceQuery=q;go('services');}else{searchQuery=q;go('search');}}
 if(form.dataset.form==='details')saveDetails(form);
 if(form.dataset.form==='sign-in'){booking.email=String(data.get('email')||'');go('verify');}
 if(form.dataset.form==='verify'){if(form.dataset.booking==='true')go('book-review');else {announce('Verification preview completed. No account has been created or signed in.');const m=document.createElement('div');m.className='notice success';m.textContent='Preview complete. No account session was created. The logged-in experience is outside this public design package.';form.replaceWith(m);}}
 if(form.dataset.form==='contact')go('contact-sent');
 if(form.dataset.form==='cookies'){$('#cookie-status').textContent='Preferences updated for this preview only. No tracking tools were enabled and no data was transmitted.';}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&currentRoute==='menu')go(lastPublicRoute);});
window.addEventListener('hashchange',render);
window.PHYSIX_SCREENS=screenList;
render();
